'use client';

import type { ReactNode } from 'react';
import { css, cx } from 'styled-system/css';

export interface SupportPanelProps {
	eyebrow?: ReactNode;
	title: ReactNode;
	description?: ReactNode;
	actions?: ReactNode;
	aside?: ReactNode;
	tone?: 'muted' | 'accent';
	className?: string;
	titleClassName?: string;
	descriptionClassName?: string;
	copyClassName?: string;
}

const styles = {
	root: css({
		display: 'grid',
		gridTemplateColumns: { base: '1fr', lg: 'minmax(0, 1fr) auto' },
		gap: '4',
		padding: { base: '5', md: '5.5' },
		borderRadius: 'l3',
		bg: 'app.surface',
		boxShadow: '{shadows.whisper}',
	}),
	rootAccent: css({
		bg: 'app.accent.soft',
		boxShadow: '{shadows.whisper}',
	}),
	copy: css({
		display: 'flex',
		flexDirection: 'column',
		gap: '2.5',
	}),
	eyebrow: css({
		textStyle: 'eyebrow',
		color: 'app.text.subtle',
	}),
	eyebrowAccent: css({
		color: 'rgba(248, 249, 249, 0.72)',
	}),
	title: css({
		textStyle: 'sectionTitle',
		color: 'app.text',
	}),
	titleAccent: css({
		color: 'app.text',
	}),
	description: css({
		textStyle: 'body',
		color: 'app.text.muted',
		maxWidth: '2xl',
		lineHeight: '1.6',
	}),
	descriptionAccent: css({
		color: 'app.text.muted',
	}),
	actions: css({
		display: 'flex',
		alignItems: 'center',
		flexWrap: 'wrap',
		gap: '2.5',
	}),
	aside: css({
		display: 'flex',
		alignItems: { base: 'flex-start', lg: 'center' },
		justifyContent: { base: 'flex-start', lg: 'flex-end' },
	}),
};

export function SupportPanel({
	eyebrow,
	title,
	description,
	actions,
	aside,
	tone = 'muted',
	className,
	titleClassName,
	descriptionClassName,
	copyClassName,
}: SupportPanelProps) {
	return (
		<section className={cx(styles.root, tone === 'accent' && styles.rootAccent, className)}>
			<div className={cx(styles.copy, copyClassName)}>
				{eyebrow && (
					<div className={cx(styles.eyebrow, tone === 'accent' && styles.eyebrowAccent)}>
						{eyebrow}
					</div>
				)}
				<div className={cx(styles.title, tone === 'accent' && styles.titleAccent, titleClassName)}>
					{title}
				</div>
				{description && (
					<div
						className={cx(
							styles.description,
							tone === 'accent' && styles.descriptionAccent,
							descriptionClassName,
						)}
					>
						{description}
					</div>
				)}
				{actions && <div className={styles.actions}>{actions}</div>}
			</div>
			{aside && <div className={styles.aside}>{aside}</div>}
		</section>
	);
}
