'use client';

import { Portal } from '@ark-ui/react/portal';
import type { ReactNode } from 'react';
import { css, cx } from 'styled-system/css';
import { CloseButton } from '../ui/close-button';
import * as Dialog from '../ui/dialog';

export interface DetailDialogProps {
	open: boolean;
	onOpenChange: (open: boolean) => void;
	title: ReactNode;
	description?: ReactNode;
	eyebrow?: ReactNode;
	actions?: ReactNode;
	children: ReactNode;
	footer?: ReactNode;
	size?: 'sm' | 'md' | 'lg' | 'xl';
	className?: string;
}

const styles = {
	accentBar: css({
		h: '2px',
		w: 'full',
		roundedTop: 'l3',
		background:
			'linear-gradient(90deg, {colors.teal.light.9}, {colors.teal.light.8}, {colors.wheat.light.9})',
	}),
	header: css({
		display: 'flex',
		flexDirection: 'column',
		gap: '3.5',
	}),
	eyebrow: css({
		textStyle: 'eyebrow',
		color: 'app.text.subtle',
	}),
	headerRow: css({
		display: 'grid',
		gridTemplateColumns: { base: '1fr', md: 'minmax(0, 1fr) auto' },
		alignItems: 'start',
		gap: '4',
		minWidth: 0,
	}),
	headerCopy: css({
		display: 'flex',
		flexDirection: 'column',
		gap: '1.5',
		minWidth: 0,
	}),
	description: css({
		color: 'app.text.muted',
		textStyle: 'small',
		maxWidth: '34rem',
	}),
	actions: css({
		display: 'flex',
		alignItems: 'center',
		flexWrap: 'wrap',
		gap: '2.5',
		justifySelf: { base: 'start', md: 'end' },
	}),
	body: css({
		display: 'flex',
		flexDirection: 'column',
		gap: '4.5',
		color: 'app.text.muted',
	}),
};

export function DetailDialog({
	open,
	onOpenChange,
	title,
	description,
	eyebrow,
	actions,
	children,
	footer,
	size = 'xl',
	className,
}: DetailDialogProps) {
	return (
		<Dialog.Root open={open} onOpenChange={(details) => onOpenChange(details.open)} size={size}>
			<Portal>
				<Dialog.Backdrop />
				<Dialog.Positioner>
					<Dialog.Content className={className}>
						<div className={styles.accentBar} />
						<Dialog.CloseTrigger asChild>
							<CloseButton size="sm" aria-label="Close dialog" />
						</Dialog.CloseTrigger>
						<Dialog.Header className={styles.header}>
							{eyebrow && <div className={styles.eyebrow}>{eyebrow}</div>}
							<div className={styles.headerRow}>
								<div className={styles.headerCopy}>
									<Dialog.Title>{title}</Dialog.Title>
									{description && (
										<Dialog.Description className={styles.description}>
											{description}
										</Dialog.Description>
									)}
								</div>
								{actions && <div className={styles.actions}>{actions}</div>}
							</div>
						</Dialog.Header>
						<Dialog.Body className={cx(styles.body)}>{children}</Dialog.Body>
						{footer && <Dialog.Footer>{footer}</Dialog.Footer>}
					</Dialog.Content>
				</Dialog.Positioner>
			</Portal>
		</Dialog.Root>
	);
}
